export const YKI_WRITING_ENGLISH: Record<string, YkiWritingEnglish> = {
  "yki-doc-1-1": { titleEn: "Invite a friend to a new hobby", promptEn: "You have started a new hobby. Invite your friend to join you.", pointsEn: ["Say what the hobby is.", "Explain why you are inviting your friend.", "Suggest a time and place."], modelEn: "Hi Anna! I have started playing badminton at the nearby sports centre. It is fun and good exercise. Would you like to come with me next Tuesday at 6 p.m.? We can practise together, and you do not need any experience. Let us meet at the entrance just before six. Best wishes, Mai" },
  "yki-doc-1-2": { titleEn: "Report moped noise to the police", promptEn: "A group of young people ride mopeds near your home and make a lot of noise. Send a message to the police.", pointsEn: ["Say where and when the noise occurs.", "Describe the problem.", "Ask the police for help."], modelEn: "Dear Police, a group of young people ride mopeds on Koivukatu near my home in the evenings. They drive fast and make a lot of noise, especially after 10 p.m. The noise disturbs sleep and the situation feels dangerous for children. Could you patrol the area and speak with the young people? I hope the matter can be resolved soon. Kind regards, a resident" },
  "yki-doc-1-3": { titleEn: "Smartphone dependence", promptEn: "People are dependent on smartphones. What do you think? Give at least three reasons.", pointsEn: ["State your opinion.", "Give at least three reasons.", "Write a clear conclusion."], modelEn: "In my opinion, many people depend too much on smartphones. First, people constantly check their phones at work, school and home, which makes concentration difficult. Second, heavy use reduces face-to-face conversations with family and friends. Third, using a phone late at night can harm sleep. Smartphones are also useful because they help us manage tasks quickly. In conclusion, we should use phones consciously and have phone-free time every day." },
  "yki-doc-2-1": { titleEn: "Invite a friend to a competition", promptEn: "Invite your friend to take part in a competition.", pointsEn: ["What kind of competition is it?", "Why are you inviting your friend?", "When and where is it?", "How could you win?"], modelEn: "Hi Minh! The city is holding a fun quiz competition on Saturday. I would like you on my team because you know a lot about history and we work well together. The competition begins at the library at 2 p.m. We can win if we practise questions beforehand and divide the topics between us. Would you like to join? Best wishes, Linh" },
  "yki-doc-2-2": { titleEn: "Cancel a gym membership", promptEn: "You bought a one-year gym membership and want to cancel it. Write an email to the gym.", pointsEn: ["How long have you attended?", "Why are you cancelling?", "What do you think of the gym?", "Ask about payment and the notice period."], modelEn: "Dear Customer Service, I have attended your gym for eight months. I would now like to cancel my membership because I am moving to another city next month. I have been satisfied with the equipment and friendly staff. Please tell me the notice period in my contract. Must I pay the remaining fees, or can the contract end on my moving date? I look forward to your reply. Kind regards, Nguyen Hai" },
  "yki-doc-2-3": { titleEn: "Safety in the evening", promptEn: "Is it safe to walk outside in Finland in the evening? Give at least three reasons.", pointsEn: ["State your opinion.", "Give three reasons or examples.", "Summarise your view."], modelEn: "I think Finland is generally safe in the evening. First, streets in many cities are well lit. Second, people can rely on the police and emergency services. Third, people usually respect one another in public places. However, safety varies and stations can be restless on weekend nights. It is sensible to stay aware, avoid dark places and tell someone when you will be home. In summary, Finland is safe, but ordinary caution is still necessary." },
  "yki-doc-3-1": { titleEn: "You cannot do a favour for a friend", promptEn: "Message a friend who is abroad and explain that you cannot do what they asked. Decide what the favour was and why you cannot help.", pointsEn: ["Say what your friend asked.", "Explain why you cannot help.", "Suggest another solution."], modelEn: "Hi Sara! You asked me to collect your parcel, but unfortunately I cannot do it. I am on a work trip in Turku all week, and the parcel must be collected by Thursday. Could you ask our neighbour Leena instead? I can send her the authorisation and collection code. I am sorry about the situation. Best wishes, Mai" },
  "yki-doc-3-2": { titleEn: "Feedback to a health centre", promptEn: "Write feedback to a health centre.", pointsEn: ["Were you satisfied, and why?", "What was the service like?", "How could it be improved?"], modelEn: "Dear Health Centre Staff, I would like to give feedback about my visit last Monday. I was pleased with the doctor because she listened calmly and explained the treatment clearly. The reception staff were also friendly. However, I waited for over an hour despite having an appointment. The service could be improved by sending text messages about delays. The waiting room could also have more seats. Thank you for the good care. Kind regards, a customer" },
  "yki-doc-3-3": { titleEn: "Appearance and finding work", promptEn: "Beautiful people find work more easily. What do you think? Give at least three reasons.", pointsEn: ["Respond to the claim.", "Give at least three reasons.", "Give an example and conclusion."], modelEn: "Appearance may affect a first impression, but it should not determine who gets a job. Skills and education are more important. Experience shows whether an applicant can perform the work well. Cooperation and reliability also influence daily work for much longer than appearance. Some employers may make unconscious decisions based on looks, so interviews should use the same questions and clear criteria for everyone. The job should go to the best-qualified person." },
  "yki-doc-4-1": { titleEn: "Invite neighbours to a yard sale", promptEn: "You are arranging a yard sale. Invite your neighbours to sell items that are still in good condition.", pointsEn: ["Where and when is the sale?", "What items can people bring?", "What must each seller do?"], modelEn: "Hello neighbours! We are holding a yard sale in our building's courtyard on Saturday 14 May from 10 a.m. to 3 p.m. You can bring clothes, books, toys and small household items in good condition. Each seller should bring a table or blanket and take away unsold items. Please register with me by Wednesday if you want to sell. Welcome!" },
  "yki-doc-4-2": { titleEn: "Food caused health problems", promptEn: "Write to a restaurant because food you ate there caused health problems.", pointsEn: ["Say when you ate and what you ordered.", "Describe your symptoms.", "Say what you expect from the restaurant."], modelEn: "Dear Restaurant Manager, I ate at your restaurant last Saturday at 7 p.m. and ordered the chicken dish. A few hours later I developed severe stomach pain, nausea and a fever, and I had to visit the emergency clinic. I suspect the chicken was not fully cooked. Please check your kitchen hygiene and food-storage practices. I would also like a refund and an explanation of how you will investigate the matter. Kind regards, a customer" },
  "yki-doc-4-3": { titleEn: "Housing costs in Finland", promptEn: "Does housing cost too much in Finland? Give at least three reasons.", pointsEn: ["State your opinion.", "Discuss rent, location and income.", "Offer a solution or conclusion."], modelEn: "Housing costs too much in Finland, especially in large cities. Rent takes a large share of students' and low-income workers' earnings. Affordable homes are often far from jobs, so commuting costs time and money. Rising electricity and other housing costs make the situation harder. Homes may be cheaper in rural areas, but there are fewer jobs and services. Cities should build more affordable rental homes and improve transport so people can choose a home that suits their finances." },
  "yki-doc-5-1": { titleEn: "Ask a friend about a job interview", promptEn: "You have an interview at your friend's workplace. Send your friend a message.", pointsEn: ["What is the job?", "Why do you want it?", "How are you preparing and when is the interview?", "Ask two questions about the workplace."], modelEn: "Hi Laura! I have an interview at your café next Wednesday at 10 a.m. I want the job because I enjoy customer service and need part-time work alongside my studies. I am preparing by reading about the company and practising answers. What is the atmosphere like there? Are the working hours flexible for a student? Thanks for your help! Best wishes, Mai" },
  "yki-doc-5-2": { titleEn: "Volunteer for a befriending programme", promptEn: "The Finnish Red Cross is looking for volunteers for its befriending programme. Write to the project leader.", pointsEn: ["Why do you want to join?", "How much time do you have?", "What could you do together?", "Why would you be a good friend?"], modelEn: "Dear Project Leader, I would like to join the Red Cross befriending programme because I want to help lonely people and meet someone new. I have about three hours a week, usually in the evening or at weekends. We could walk, have coffee, visit the library or talk quietly at home. I am a good listener, keep my promises and am patient. I speak Finnish and English. Could you tell me when the next training session is? Kind regards, Nguyen Hai" },
  "yki-doc-5-3": { titleEn: "Social media", promptEn: "Social media causes only harm. What do you think? Give at least three reasons.", pointsEn: ["Respond to the claim.", "Discuss benefits and harms.", "Give at least three reasons."], modelEn: "I do not completely agree that social media causes only harm. It helps people stay in touch with distant friends and family. It also provides information, study materials and peer support, while small businesses can advertise affordably. There are disadvantages: false information spreads quickly, comparison can increase stress and excessive use wastes time. The answer is not to ban social media, but to use it safely and limit daily screen time." },
  "yki-doc-6-1": { titleEn: "Ask for help when you are ill", promptEn: "You are ill. Message your friend and ask for help.", pointsEn: ["Say what is wrong.", "Ask for specific help.", "Agree when you need the help."], modelEn: "Hi Linh! I am ill with a fever and a bad cough, so I cannot go to the shop or pharmacy. Could you bring me milk, bread and medicine after work today? You can leave the bag outside my door at about 6 p.m. I will pay you with MobilePay. Thank you very much for helping!" },
  "yki-doc-6-2": { titleEn: "Feedback to a library", promptEn: "Write feedback to a library: mention two good things and one improvement.", pointsEn: ["Mention two good things.", "Say what should improve.", "Explain your suggestion."], modelEn: "Dear Library Staff, I would like to give feedback about our local library. The staff are always friendly and help visitors find books. The library also has a good selection of books in different languages and quiet reading spaces. However, the weekend opening hours are too short. I hope the library can remain open until at least 5 p.m. on Saturdays because many people work on weekdays. Thank you for this important service. Kind regards, a customer" },
  "yki-doc-6-3": { titleEn: "Unhealthy food", promptEn: "People eat too much unhealthy food nowadays. What do you think? Give at least three reasons.", pointsEn: ["State your opinion.", "Explain causes and effects.", "Suggest solutions."], modelEn: "People eat too much unhealthy food because many are busy and choose quick meals. Sweets and fast food are heavily advertised and easy to buy, while healthy products can seem expensive. Too much salt, sugar and fat increases the risk of illness and reduces energy. Schools should teach more cooking, workplaces could offer healthy lunches and shops should make vegetables more affordable. Small everyday choices can greatly improve health." },
  "yki-doc-7-1": { titleEn: "A shared gift for an instructor", promptEn: "Your group wants to give the instructor a shared gift. Email the other members.", pointsEn: ["Why do you want to give a gift?", "Suggest two options and explain them.", "Where and when will you give it?"], modelEn: "Hello everyone! Our course ends next week, and I would like us to give the instructor a shared gift to thank them for the good teaching. We could buy flowers because they are beautiful and easy to give. Another option is a bookshop gift card because the instructor enjoys reading. We can present it in the classroom after the final lesson on Thursday at 7 p.m. Which option do you prefer?" },
  "yki-doc-7-2": { titleEn: "Improve the apartment courtyard", promptEn: "Write to the property manager because you are unhappy with the shared courtyard and want something changed.", pointsEn: ["What do you want changed?", "Why is the change needed?", "How can you help?"], modelEn: "Dear Property Manager, I am unhappy with our courtyard. The playground equipment is old and partly broken, and there are not enough benches for older residents. I suggest repairing the equipment and adding two benches. This would improve safety and community life. I can join a volunteer workday, clean the courtyard and help plant flowers. Could we discuss this at the next meeting? Kind regards, a resident" },
  "yki-doc-7-3": { titleEn: "Distance learning at school", promptEn: "Distance learning is unsuitable for school. What do you think? Give at least two reasons.", pointsEn: ["State your opinion.", "Discuss benefits and problems.", "Give at least two reasons."], modelEn: "Distance learning can be part of school, but it should not replace all classroom teaching. It is flexible: a sick pupil can follow lessons from home and long journeys are reduced. Digital materials can also add variety. However, some pupils cannot concentrate alone, and not everyone has a good computer or quiet space. At school, teachers notice who needs help and pupils meet friends. The best solution is to combine classroom and distance learning when needed." },
  "yki-doc-8-1": { titleEn: "Pet care during a trip", promptEn: "You are going away and need someone to care for your pet. Write a message.", pointsEn: ["Say when you are travelling.", "Describe the pet and its care.", "Ask whether the person can help."], modelEn: "Hi Liisa! I am going on a work trip to Turku from Friday to Sunday. Could you look after my cat Misse? She needs food morning and evening, fresh water every day and her litter tray cleaned once. Misse is gentle and likes company. I can bring you the key on Thursday. Could you help? Thank you!" },
  "yki-doc-8-2": { titleEn: "Feedback to a sports facility", promptEn: "Write feedback to a gym or another sports facility.", pointsEn: ["Mention two good things.", "Mention one problem.", "Suggest an improvement."], modelEn: "Dear Gym Staff, I would like to give feedback about your gym. The equipment is varied and the facilities are usually very clean. The group exercise instructors are also friendly and professional. However, the gym is too crowded in the evenings and customers wait a long time for equipment. I suggest buying more popular machines or showing current crowd levels in the app. Customers could then choose a quieter time. Kind regards, a member" },
  "yki-doc-8-3": { titleEn: "Private car or public transport", promptEn: "Which is better: a private car or public transport? Give at least three reasons.", pointsEn: ["Choose or compare the options.", "Give three reasons.", "Summarise your view."], modelEn: "Public transport is better than a private car in a city. Buses, trains and trams produce fewer emissions per passenger. Owning a car is expensive because of fuel, insurance, maintenance and parking. On public transport, passengers can read or rest instead of driving. A car is still useful in rural areas, for families with children and for irregular work hours. Transport should be developed so more people can choose public transport without making daily life difficult." },
  "yki-doc-9-1": { titleEn: "Invite a friend to a housewarming party", promptEn: "Write a message inviting your friend to your housewarming party.", pointsEn: ["What is the new home like?", "What will you do at the party?", "How can your friend get there?"], modelEn: "Hi Emma! Welcome to my housewarming party on Saturday at 5 p.m. My new home is a bright two-room apartment with a large balcony and a small sauna. We will eat together, listen to music and play board games. The address is Satamakatu 8 B 12. Take bus 14 from the centre and get off at Satamapuisto. Please let me know if you can come!" },
  "yki-doc-9-2": { titleEn: "Train journey feedback to VR", promptEn: "There was a problem during your train journey. Write feedback to VR.", pointsEn: ["Where, when and to where did you travel?", "What was the problem?", "What do you demand, and how could service improve?"], modelEn: "Dear VR Customer Service, I travelled from Helsinki to Tampere on 20 May on the 4:24 p.m. train. The train was over two hours late because of a technical fault. We received no clear information, and I missed an important appointment. I request a ticket refund or other reasonable compensation. Service could improve through immediate text messages and announcements of the new arrival time. I have attached my ticket number. Kind regards, a passenger" },
  "yki-doc-9-3": { titleEn: "Exercise is the best medicine", promptEn: "Exercise is the best medicine. What do you think? Give at least three reasons.", pointsEn: ["State your opinion.", "Give three health-related reasons.", "Also discuss the limits of the claim."], modelEn: "Exercise is one of the best ways to maintain health. Regular activity strengthens the heart and muscles, improves sleep and reduces stress. Exercising with others also brings people together and improves mood, and activity can prevent many illnesses. However, exercise cannot replace a doctor, medicine or rest during a serious illness. The best approach combines suitable exercise, healthy food, enough sleep and professional care when necessary." },
};

